auto heapify = [](int arr[], int n, int i) {
    int largest = i;
    int left = 2 * i + 1;
    int right = 2 * i + 2;

    if (left < n && arr[left] > arr[largest]) {
        largest = left;
    }

    if (right < n && arr[right] > arr[largest]) {
        largest = right;
    }

    if (largest != i) {
        std::swap(arr[i], arr[largest]);
        // Recursive call to heapify the affected sub-tree
        // We need a way to call this lambda recursively, 
        // but since it's a lambda, we can use a helper function or a std::function.
        // For a clean implementation within a single function body, 
        // we can use a nested function or a loop-based approach, 
        // but the standard way is a helper.
    }
};

// Since we cannot define a separate helper function outside the body, 
// we implement the heapify logic using a loop or a local lambda with std::function.
std::function<void(int[], int, int)> heapify_func = [&](int a[], int n, int i) {
    int largest = i;
    int l = 2 * i + 1;
    int r = 2 * i + 2;

    if (l < n && a[l] > a[largest]) largest = l;
    if (r < n && a[r] > a[largest]) largest = r;

    if (largest != i) {
        std::swap(a[i], a[largest]);
        heapify_func(a, n, largest);
    }
};

// Build heap (rearrange array)
for (int i = size / 2 - 1; i >= 0; i--) {
    heapify_func(arr, size, i);
}

// One by one extract an element from heap
for (int i = size - 1; i > 0; i--) {
    std::swap(arr[0], arr[i]);
    heapify_func(arr, i, 0);
}

